/**
 * Storage for computed routes. Server-only.
 *
 * Read precedence (POPRAVKI_1 §4):
 *   1. Supabase table `trase`, when Supabase is configured;
 *   2. otherwise the committed route files in data/trase/ — generated by
 *      `npm run trase -- --preracunaj --zapisi-v-repo` and committed on
 *      purpose, so routed geometry ships with the code and needs neither a
 *      database nor an ORS key in production;
 *   3. otherwise nothing — every stage is drawn from the schematic fallback
 *      (lib/trase.ts sestaviObroc), marked "shematsko".
 *
 * Each committed file carries its cache key (`kljuc`), so a file that no
 * longer matches the current points is detected as stale and never served,
 * exactly like a stale Supabase row.
 *
 * The public site never writes here and never calls the routing service:
 * writes happen only from `npm run trase` (and, later, admin server code).
 *
 * One row/file per building block: saving a route replaces any older one
 * for the same `etapa_ids`, so "the" route for a stage is unambiguous.
 */

import { mkdirSync, readFileSync, readdirSync, unlinkSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { getSupabaseClient, getSupabaseServiceClient, isSupabaseConfigured } from "@/lib/supabase";
import { istiEtapaIds } from "@/lib/trase";
import type { Trasa } from "@/lib/types";

export type NovaTrasa = Omit<Trasa, "id">;

export interface TraseRepo {
  /** Human-readable name of the backing store, for logs. */
  ime: string;
  vse(): Promise<Trasa[]>;
  shrani(trasa: NovaTrasa): Promise<void>;
}

// ---------------------------------------------------------------------------
// Supabase
// ---------------------------------------------------------------------------

function pgArray(ids: string[]): string {
  return `{${ids.map((id) => `"${id}"`).join(",")}}`;
}

const supabaseRepo: TraseRepo = {
  ime: "Supabase (tabela trase)",
  async vse() {
    const { data, error } = await getSupabaseClient().from("trase").select("*");
    if (error) throw new Error(`Napaka pri branju tras iz Supabase: ${error.message}`);
    return (data ?? []) as Trasa[];
  },
  async shrani(trasa) {
    const supabase = getSupabaseServiceClient();
    const { error } = await supabase.from("trase").upsert(trasa, { onConflict: "kljuc" });
    if (error) throw new Error(`Napaka pri zapisu trase v Supabase: ${error.message}`);
    const { error: deleteError } = await supabase
      .from("trase")
      .delete()
      .filter("etapa_ids", "eq", pgArray(trasa.etapa_ids))
      .neq("kljuc", trasa.kljuc);
    if (deleteError) throw new Error(`Napaka pri brisanju starih tras: ${deleteError.message}`);
  },
};

// ---------------------------------------------------------------------------
// Committed files (data/trase/)
// ---------------------------------------------------------------------------

export const TRASE_DIR = join(process.cwd(), "data", "trase");

/** Stable file name per building block: `etapa-3.json`, `povezava__etapa-3__etapa-4.json`. */
function imeDatoteke(etapaIds: string[]): string {
  return etapaIds.length === 1 ? `${etapaIds[0]}.json` : `povezava__${etapaIds.join("__")}.json`;
}

function datotekeTras(): string[] {
  try {
    return readdirSync(TRASE_DIR).filter((f) => f.endsWith(".json"));
  } catch {
    return []; // no directory = nothing committed = schematic fallback
  }
}

/** True when at least one committed route file exists. */
export function imaShranjeneDatoteke(): boolean {
  return datotekeTras().length > 0;
}

/** Readable diffs: metadata one field per line, geometry and legs one line each. */
function zapisi(trasa: Trasa): string {
  const { geometry, kraki, ...ostalo } = trasa;
  const glava = JSON.stringify(ostalo, null, 2).slice(0, -2);
  return `${glava},\n  "kraki": ${JSON.stringify(kraki)},\n  "geometry": ${JSON.stringify(geometry)}\n}\n`;
}

const datotekeRepo: TraseRepo = {
  ime: "datoteke v data/trase/ (v repozitoriju)",
  async vse() {
    return datotekeTras().map((f) => JSON.parse(readFileSync(join(TRASE_DIR, f), "utf-8")) as Trasa);
  },
  async shrani(trasa) {
    mkdirSync(TRASE_DIR, { recursive: true });
    const ime = imeDatoteke(trasa.etapa_ids);
    // Defensive: drop any other file for the same block (e.g. renamed by hand).
    for (const f of datotekeTras()) {
      if (f === ime) continue;
      const obstojeca = JSON.parse(readFileSync(join(TRASE_DIR, f), "utf-8")) as Trasa;
      if (istiEtapaIds(obstojeca.etapa_ids, trasa.etapa_ids)) unlinkSync(join(TRASE_DIR, f));
    }
    // The file name is the ID: stable across recomputes, so diffs stay small.
    writeFileSync(join(TRASE_DIR, ime), zapisi({ id: ime.replace(/\.json$/, ""), ...trasa }), "utf-8");
  },
};

// ---------------------------------------------------------------------------

/** The store the public site reads from (precedence above). */
export function getTraseRepo(): TraseRepo {
  return isSupabaseConfigured() ? supabaseRepo : datotekeRepo;
}

/** The committed-files store, for `npm run trase -- --zapisi-v-repo`. */
export function getRepoDatoteke(): TraseRepo {
  return datotekeRepo;
}
